new Promise((done) => {
  const root = document.querySelector('[role="img"][aria-label^="Before"]');
  const camera = root.querySelectorAll(".aspect-video")[1].firstElementChild;
  const cursor = camera.querySelector(".pointer-events-none");
  const atRest = () => {
    const m = new DOMMatrix(getComputedStyle(cursor).transform);
    return Math.abs(m.m41 - camera.offsetWidth * 0.3) < 0.5 && Math.abs(m.m42 - camera.offsetHeight * 0.86) < 0.5;
  };
  let left = false;
  const id = setInterval(() => {
    if (!atRest()) left = true;
    else if (left) { clearInterval(id); done(); }
  }, 16);
})
